describe('persistSessionAccessToken', () => {
  const Keychain = require('react-native-keychain') as {
    setGenericPassword: jest.Mock;
  };

  beforeEach(() => {
    Keychain.setGenericPassword.mockClear();
  });

  it('does not write a null or empty token to Keychain', async () => {
    await persistSessionAccessToken(null);
    await persistSessionAccessToken(undefined);
    await persistSessionAccessToken('');
    await persistSessionAccessToken('   ');
    expect(Keychain.setGenericPassword).not.toHaveBeenCalled();
  });

  it('writes a usable access token', async () => {
    await persistSessionAccessToken('access-token');
    expect(Keychain.setGenericPassword).toHaveBeenCalledWith(
      'password',
      'access-token',
    );
  });
});

